package com.optarena;

public class SignupService {
    public String register(String username) {
        String u = username == null ? "" : username.trim();
        if (u.length() < 3 || u.length() > 20) {
            return "invalid";
        }
        return "registered:" + u.toLowerCase();
    }
}

