package com.optarena;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class UsernameRefactorHiddenTest {

    @Test
    void signupAcceptsThreeCharName() {
        assertEquals("registered:bob", new SignupService().register(" Bob "));
    }

    @Test
    void signupRejectsTooShortAndTooLong() {
        assertEquals("invalid", new SignupService().register("ab"));
        assertEquals("invalid", new SignupService().register("a".repeat(21)));
    }

    @Test
    void profileAcceptsAndRejects() {
        assertEquals("updated:alice", new ProfileService().update("Alice"));
        assertEquals("invalid", new ProfileService().update(null));
    }
}

